contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (1));
        require(address(this).balance >= 1);
        c.deposit{value: 1}(); if (__ESBMC_reverted()) return;

        uint256 beforeBalance = address(c).balance;
        uint256 targetBefore = target.balance;

        bool reverted;
        c.migrateTo(target); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = address(c).balance;
        assert(reverted ? afterBalance == beforeBalance : (afterBalance == 0 && target.balance == targetBefore + beforeBalance));
    }

    receive() external payable {}
}

